#
# Test GetStyles with more complex styling
#
# REQUIRES: INPUT=GDAL OUTPUT=PNG SUPPORTS=WMS
#
# RUN_PARMS: wms_getstyles_point_outline.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_outline" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_x.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_x" > [RESULT_DEMIME]

# RUN_PARMS: wms_getstyles_polygon_backslash.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_backslash" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_polygon_horline.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_horline" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_polygon_slash.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_slash" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_polygon_vertline.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_vertline" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_polygon_snap_to_slash.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_snap_to_slash" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_oval.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_oval" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_notched_rect.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_notched_rect" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_pentagon.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=pentagon" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_hexagon.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=hexagon" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_wave.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=wave" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_polygon_square_spaced.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=polygon_square_spaced" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_notched_rect_rotated.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_notched_rect_rotated" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_notched_rect_offset.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_notched_rect_offset" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_notched_rect_opacity.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_notched_rect_opacity" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_chevron.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_chevron" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_circle_no_outline.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_circle_no_outline" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_oval_rotated.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_oval_rotated" > [RESULT_DEMIME]
# RUN_PARMS: wms_getstyles_point_oval_opacity.xml [MAPSERV] QUERY_STRING="map=[MAPFILE]&SERVICE=WMS&VERSION=1.3.0&REQUEST=GetStyles&layers=point_oval_opacity" > [RESULT_DEMIME]

MAP
    NAME TEST_SLD_COMPLEX
    SIZE 300 300

    PROJECTION
        "epsg:4326"
    END

    WEB
      METADATA
        "wms_onlineresource"   "http://localhost/path/to/wms_simple?"
        "ows_enable_request" "*"
      END
    END

    SYMBOL
        NAME "circle"
        TYPE ELLIPSE
        FILLED TRUE
        POINTS
            1 1
        END
    END

    SYMBOL
        NAME "pentagon"
        TYPE VECTOR
        FILLED TRUE
        POINTS
            0.5 0
            1 0.38
            0.81 1
            0.19 1
            0 0.38
            0.5 0
        END
    END

    SYMBOL
        NAME "hexagon"
        TYPE VECTOR
        FILLED TRUE
        POINTS
            93.3 75
            93.3 25
            50 0
            6.7 25
            6.7 75
            50 100
            93.3 75
        END
    END

    SYMBOL
        NAME "oval"
        TYPE ELLIPSE
        FILLED TRUE
        POINTS
            2 1
        END
    END

    SYMBOL
        NAME "notched_rect"
        TYPE VECTOR
        FILLED TRUE
        POINTS
            16 0
            64 0
            65.22 6.12
            68.69 11.31
            73.88 14.78
            80 16
            80 44
            73.88 45.22
            68.69 48.69
            65.22 53.88
            64 60
            16 60
            14.78 53.88
            11.31 48.69
            6.12 45.22
            0 44
            0 16
            6.12 14.78
            11.31 11.31
            14.78 6.12
            16 0
        END
    END

    SYMBOL
        NAME "x" # must be named "x" to match the SLD WellKnownName, and lower-case
        TYPE VECTOR
        FILLED FALSE
        POINTS
            0 0
            1 1
            -99 -99
            0 1
            1 0
        END
    END

    SYMBOL
        NAME "hatch"
        TYPE hatch
    END

    SYMBOL
        NAME "wave"
        TYPE VECTOR
        FILLED FALSE
        POINTS
            0 0.5
            0.083 0.675
            0.167 0.803
            0.25 0.85
            0.333 0.803
            0.417 0.675
            0.5 0.5
            0.583 0.325
            0.667 0.197
            0.75 0.15
            0.833 0.197
            0.917 0.325
            1 0.5
        END
    END

    SYMBOL
        NAME "square_spaced"
        TYPE VECTOR
        FILLED TRUE
        POINTS
            0.375 0.375
            0.625 0.375
            0.625 0.625
            0.375 0.625
            0.375 0.375
        END
    END

    SYMBOL
        NAME "chevron"
        TYPE VECTOR
        FILLED FALSE
        POINTS
            0 1
            0.5 0
            1 1
        END
    END

    LAYER
        NAME "point_outline"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "circle"
                COLOR "#156082"
                OUTLINECOLOR 255 0 0
                SIZE 16
            END
        END
    END

    LAYER
        NAME "point_x"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "x"
                COLOR 0 0 0
                WIDTH 2
                SIZE 10
            END
        END
    END

    LAYER
        NAME "polygon_backslash"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                COLOR 0 0 255
                SYMBOL "hatch"
                ANGLE -45
                WIDTH 0.5
                SIZE 6 # not output to the SLD
            END
        END
    END

    LAYER
        NAME "polygon_horline"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                COLOR 0 0 255
                SYMBOL "hatch"
                ANGLE 0
                WIDTH 0.5
                SIZE 6 # not output to the SLD
            END
        END
    END

    LAYER
        NAME "polygon_slash"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                COLOR 0 0 255
                SYMBOL "hatch"
                ANGLE 45
                WIDTH 0.5
                SIZE 6 # not output to the SLD
            END
        END
    END

    LAYER
        NAME "polygon_vertline"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                COLOR 0 0 255
                SYMBOL "hatch"
                ANGLE 90
                WIDTH 0.5
                SIZE 6 # not output to the SLD
            END
        END
    END

    LAYER
        NAME "polygon_snap_to_slash"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                COLOR 0 0 255
                SYMBOL "hatch"
                ANGLE 30
                WIDTH 0.5
                SIZE 6 # not output to the SLD
            END
        END
    END

    LAYER
        NAME "point_oval"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "oval"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
            END
        END
    END

    LAYER
        NAME "point_notched_rect"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "notched_rect"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
            END
        END
    END

    LAYER
        NAME "pentagon"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "pentagon"
                COLOR "#156082"
                OUTLINECOLOR 255 0 0
                SIZE 16
            END
        END
    END

    LAYER
        NAME "hexagon"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "hexagon"
                COLOR "#156082"
                OUTLINECOLOR 255 0 0
                SIZE 16
            END
        END
    END

    LAYER
        NAME "wave"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "wave"
                COLOR "#4A90D9"
                WIDTH 1
                SIZE 8
            END
        END
    END

    LAYER
        NAME "polygon_square_spaced"
        TYPE POLYGON
        FEATURE
            POINTS
                0 0
                0 10
                10 10
                10 0
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "square_spaced"
                COLOR "#FFC000"
                SIZE 5
            END
        END
    END

    LAYER
        NAME "point_notched_rect_rotated"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "notched_rect"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
                ANGLE 45
            END
        END
    END

    LAYER
        NAME "point_notched_rect_offset"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "notched_rect"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
                OFFSET 5 -3
            END
        END
    END

    LAYER
        NAME "point_notched_rect_opacity"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "notched_rect"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
                OPACITY 50
            END
        END
    END

    LAYER
        NAME "point_chevron"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "chevron"
                COLOR "#000000"
                WIDTH 2
                SIZE 12
            END
        END
    END

    LAYER
        NAME "point_circle_no_outline"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "circle"
                COLOR "#156082"
                SIZE 16
            END
        END
    END

    LAYER
        NAME "point_oval_rotated"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "oval"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
                ANGLE 45
            END
        END
    END

    LAYER
        NAME "point_oval_opacity"
        TYPE POINT
        FEATURE
            POINTS
                0 0
            END
        END
        CLASS
            STYLE
                SYMBOL "oval"
                COLOR "#8FC1FF"
                OUTLINECOLOR "#B5B7B8"
                SIZE 10
                OPACITY 40
            END
        END
    END


END
